    }
  };

  for (int i = 0; i < succs.count; ++i) consider(succs.indices[i], false);

  if (next_idx == current_idx) {
    for (int i = 0; i < succs.count; ++i) consider(succs.indices[i], true);
  }

  if (next_idx == current_idx) {
    RCLCPP_WARN(logger_, "D* Lite extraction stuck");
    return plan;
  }

